(function(){'use strict';const $=id=>document.getElementById(id);let moving=false,drag=null,playing=false,timer=null;
function button(parent,text,fn){const b=document.createElement('button');b.type='button';b.textContent=text;b.addEventListener('click',fn);parent.append(b);return b;}
function stop(){const button=$('discovery-play');if(button){button.textContent='Play animation';button.setAttribute('aria-pressed','false');}playing=false;clearInterval(timer);timer=null;$('beam-sketch').classList.remove('discovery-animate');}
window.MT_DISCOVERY_CONTROLS=function(id){stop();moving=false;drag=null;const previous=$('discovery-controls');previous?.remove();const toolbar=document.createElement('div');toolbar.id='discovery-controls';toolbar.className='discovery-actions';$('model-fields').after(toolbar);
 if(id==='section'){
  button(toolbar,'Add component',()=>{const form=$('experiment');for(let i=1;i<=6;i++)if(form.elements.namedItem('shape'+i).value==='none'){form.elements.namedItem('shape'+i).value='rectangle';const details=form.elements.namedItem('shape'+i).closest('details');if(details)details.open=true;window.MT_MODEL_UI.update();return;}status('All six component slots are in use. Set a shape to Not used to remove it.');});
  const toggle=button(toolbar,'Move components in diagram',()=>{moving=!moving;toggle.setAttribute('aria-pressed',String(moving));$('beam-sketch').classList.toggle('discovery-moving',moving);if(moving){svg.scrollIntoView({block:'center',behavior:'auto'});svg.focus({preventScroll:true});}status(moving?'Drag a solid or hole by its numbered shape. Pan / pinch must be off. Coordinate fields remain available.':'Component dragging is off.');});toggle.setAttribute('aria-pressed','false');
 }else if(id==='gears'||id==='waves'){
  const b=button(toolbar,'Play animation',()=>{if(playing){stop();b.textContent='Play animation';b.setAttribute('aria-pressed','false');return;}playing=true;b.textContent='Pause animation';b.setAttribute('aria-pressed','true');if(id==='gears')$('beam-sketch').classList.add('discovery-animate');else timer=setInterval(()=>{if(document.hidden)return;const state=window.MT_MODEL_UI.state();if(!state||state.id!=='waves'){stop();return;}const input=$('experiment').elements.namedItem('time');input.value=String((Number(input.value)+1/(state.inputs.frequency*24))%10);input.dispatchEvent(new Event('input',{bubbles:true}));},80);});b.id='discovery-play';b.setAttribute('aria-pressed','false');const text=document.createElement('p');text.className='helper';text.textContent=id==='gears'?'Animation slows every shaft by the same display factor. Result values retain the calculated rpm.':'Animation advances wave phase slowly; the input shows the model time. Doppler traces show complete stationary time signals.';toolbar.append(text);
 }
 const feedback=document.createElement('p');feedback.id='discovery-status';feedback.setAttribute('role','status');toolbar.append(feedback);
};
function status(text){const n=$('discovery-status');if(n)n.textContent=text;}
window.MT_DISCOVERY_RESULT=function(result){let exportButton=$('discovery-sketch-export');if(!exportButton){exportButton=document.createElement('button');exportButton.id='discovery-sketch-export';exportButton.type='button';exportButton.textContent='Geometry / sketch (SVG)';exportButton.onclick=()=>{const state=window.MT_MODEL_UI.state();if(!state||$('beam-sketch').hasAttribute('hidden'))return;window.MT_STUDY_EXPORT.download('MarineTools-'+state.id+'-sketch.svg',window.MT_STUDY_EXPORT.svgSnapshot($('beam-sketch')),'image/svg+xml');};document.querySelector('.export-actions').append(exportButton);}exportButton.hidden=!['beam','section','three-phase','gears','mohr','hydrostatics'].includes(result.kind);exportButton.disabled=result.kind==='invalid';let box=$('discovery-transfer');if(!box){box=document.createElement('p');box.id='discovery-transfer';$('model-results').after(box);}box.replaceChildren();if(result.kind==='section'){const I=result.values.Ix/1e4,a=document.createElement('a');a.textContent='Use this Ix in the beam model →';a.target='_top';a.href='interactive.html?inertia='+encodeURIComponent(I)+'#beam';if(I>=1&&I<=1e6)box.append(a);else box.textContent='This Ix is outside the beam model’s supported 1–1,000,000 cm⁴ range.';}const play=$('discovery-play');if(play&&result.kind==='waves'){play.disabled=result.waveMode==='doppler';if(play.disabled)stop();}if(playing&&result.kind==='gears')$('beam-sketch').classList.add('discovery-animate');};
const svg=$('beam-sketch');function locationAt(event){const q=svg.createSVGPoint();q.x=event.clientX;q.y=event.clientY;return q.matrixTransform(svg.getScreenCTM().inverse());}
svg.addEventListener('pointerdown',event=>{if(!moving||svg.MT_DIAGRAM_VIEW?.enabled||event.button>0)return;const index=event.target.getAttribute('data-component'),state=window.MT_MODEL_UI.state();if(!index||state?.id!=='section')return;event.preventDefault();const q=locationAt(event),g=svg.MT_SECTION_GEOMETRY,x=g.xmid+(q.x-400)/g.scale,y=g.ymid-(q.y-100)/g.scale;drag={index,dx:x-state.inputs['x'+index],dy:y-state.inputs['y'+index],geometry:{...g}};svg.MT_SECTION_DRAG_GEOMETRY={...g};svg.setPointerCapture(event.pointerId);});
svg.addEventListener('pointermove',event=>{if(!drag)return;event.preventDefault();const q=locationAt(event),g=drag.geometry,x=Math.max(-2000,Math.min(2000,g.xmid+(q.x-400)/g.scale-drag.dx)),y=Math.max(-2000,Math.min(2000,g.ymid-(q.y-100)/g.scale-drag.dy)),state=window.MT_MODEL_UI.state();if(!state)return;const c={...state.inputs,['x'+drag.index]:Number(x.toFixed(2)),['y'+drag.index]:Number(y.toFixed(2))};try{window.MT_EDUCATION_MODELS.section(c);for(const key of ['x','y'])$('experiment').elements.namedItem(key+drag.index).value=c[key+drag.index];window.MT_MODEL_UI.update();document.dispatchEvent(new Event('mt-study-changed'));status('Component '+drag.index+' moved.');}catch(error){status(error.message);}});
for(const event of ['pointerup','pointercancel','lostpointercapture'])svg.addEventListener(event,()=>{if(!drag)return;drag=null;delete svg.MT_SECTION_DRAG_GEOMETRY;if(window.MT_MODEL_UI?.active==='section')window.MT_MODEL_UI.update();});window.addEventListener('pagehide',stop);window.addEventListener('mt-module-hidden',stop);
})();
